import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authAPI, booksAPI } from '../utils/api';
import { clearUserSession, getStoredUser, saveUserSession } from '../utils/session';

const Dashboard = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [bookForm, setBookForm] = useState({
    bookTitle: '',
    author: '',
    language: ''
  });
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    const storedUser = getStoredUser();

    if (!storedUser) {
      navigate('/login', { replace: true });
      return;
    }

    const loadDashboard = async () => {
      try {
        const [userResponse] = await Promise.all([
          authAPI.getUser(storedUser.id),
          fetchUserBooks(storedUser.id)
        ]);

        const currentUser = saveUserSession(userResponse.data.user);
        setUser(currentUser);
      } catch (err) {
        clearUserSession();
        navigate('/login', { replace: true });
      } finally {
        setLoading(false);
      }
    };

    loadDashboard();
  }, [navigate]);

  const fetchUserBooks = async (userId) => {
    const response = await booksAPI.getUserBooks(userId);
    setBooks(response.data.books);
  };

  const handleBookFormChange = (e) => {
    const { name, value } = e.target;
    setBookForm(prev => ({
      ...prev,
      [name]: value
    }));
    setError('');
  };

  const handleSubmitBook = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    const bookTitle = bookForm.bookTitle.trim();
    const author = bookForm.author.trim();
    const language = bookForm.language.trim();

    if (!bookTitle || !author || !language) {
      setError('Please enter the book title, author, and language');
      return;
    }

    setSubmitting(true);

    try {
      await booksAPI.addBook(user.id, {
        bookTitle,
        author,
        language
      });

      setBookForm({
        bookTitle: '',
        author: '',
        language: ''
      });
      setSuccess('Book added successfully.');

      await fetchUserBooks(user.id);

      const updatedUser = {
        ...user,
        booksReadCount: (user.booksReadCount || 0) + 1
      };
      setUser(updatedUser);
      saveUserSession(updatedUser);

      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to add book. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleLogout = () => {
    clearUserSession();
    navigate('/');
  };

  if (loading) {
    return (
      <div className="loading">
        <div className="spinner"></div>
        <p>Loading your dashboard...</p>
      </div>
    );
  }

  if (!user) {
    return null;
  }

  return (
    <div className="dashboard-page">
      <nav className="site-nav dashboard-nav">
        <div className="brand-lockup">
          <h1>Reading Dashboard</h1>
          <p>{user.location}</p>
        </div>
        <div className="nav-actions">
          <button className="btn btn-outline btn-compact" onClick={() => navigate('/')}>
            Home
          </button>
          <button className="btn btn-secondary btn-compact" onClick={handleLogout}>
            Logout
          </button>
        </div>
      </nav>

      <main className="dashboard-shell">
        <section className="dashboard-hero">
          <div>
            <p className="eyebrow dark">Welcome back</p>
            <h2>{user.firstName} {user.lastName}</h2>
            <p>
              Keep your reading record complete by adding every finished book
              with its title, author, and language.
            </p>
          </div>
          <div className="dashboard-profile">
            <span>{user.category}</span>
            {user.category === 'Student' && user.class !== 'N/A' && <strong>Class {user.class}</strong>}
          </div>
        </section>

        <section className="dashboard-grid">
          <div className="metric-card">
            <p>Total Books Read</p>
            <strong>{user.booksReadCount || 0}</strong>
            <span>Personal contribution</span>
          </div>
          <div className="metric-card">
            <p>Recorded Entries</p>
            <strong>{books.length}</strong>
            <span>Books in your history</span>
          </div>
          <div className="metric-card">
            <p>Region</p>
            <strong>{user.region}</strong>
            <span>{user.location}</span>
          </div>
        </section>

        <section className="workspace-grid">
          <form className="panel-card book-form" onSubmit={handleSubmitBook}>
            <div className="panel-heading">
              <p className="eyebrow dark">New Entry</p>
              <h3>Record a Book</h3>
            </div>

            {error && <div className="error">{error}</div>}
            {success && <div className="success">{success}</div>}

            <div className="form-group">
              <label>Book Title</label>
              <input
                type="text"
                name="bookTitle"
                value={bookForm.bookTitle}
                onChange={handleBookFormChange}
                placeholder="Enter the book title"
                disabled={submitting}
              />
            </div>

            <div className="form-group">
              <label>Author</label>
              <input
                type="text"
                name="author"
                value={bookForm.author}
                onChange={handleBookFormChange}
                placeholder="Enter the author's name"
                disabled={submitting}
              />
            </div>

            <div className="form-group">
              <label>Language</label>
              <select
                name="language"
                value={bookForm.language}
                onChange={handleBookFormChange}
                disabled={submitting}
              >
                <option value="">Select language</option>
                <option value="English">English</option>
                <option value="Urdu">Urdu</option>
                <option value="Sindhi">Sindhi</option>
                <option value="Gujarati">Gujarati</option>
                <option value="Other">Other</option>
              </select>
            </div>

            <button type="submit" className="btn" disabled={submitting}>
              {submitting ? 'Adding...' : 'Add Book'}
            </button>
          </form>

          <section className="panel-card history-panel">
            <div className="panel-heading horizontal">
              <div>
                <p className="eyebrow dark">History</p>
                <h3>Your Reading Log</h3>
              </div>
              <span>{books.length} books</span>
            </div>

            {books.length === 0 ? (
              <div className="empty-state">
                <p>No books recorded yet. Add your first completed book.</p>
              </div>
            ) : (
              <div className="table-scroll">
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>#</th>
                      <th>Book Title</th>
                      <th>Author</th>
                      <th>Language</th>
                      <th>Date</th>
                    </tr>
                  </thead>
                  <tbody>
                    {books.map((book, index) => (
                      <tr key={book.id}>
                        <td>{books.length - index}</td>
                        <td><strong>{book.bookTitle}</strong></td>
                        <td>{book.author}</td>
                        <td>{book.language}</td>
                        <td>
                          {new Date(book.recordedAt).toLocaleDateString('en-US', {
                            year: 'numeric',
                            month: 'short',
                            day: 'numeric'
                          })}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </section>
        </section>
      </main>
    </div>
  );
};

export default Dashboard;
